// Input: act_id (requerido), slack_channel_id (opcional), client_name (opcional), date_preset (opcional)
const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json;
  const act_id = (j.act_id || j.meta_ad_account_id || '').toString().trim();
  const date_preset = j.date_preset || 'last_7d';
  const client_name = j.client_name || j.name || 'Cliente';
  const slack_channel_id = j.slack_channel_id || null;
  const strategy = j.strategy || j.product_angle || '';
  const client_id = j.client_id || 'c557c9d1-8f1a-4d91-9fe0-95e8ac298e64';
  if (!act_id || !act_id.startsWith('act_')) {
    out.push({ json: { error: 'act_id requerido (ej. act_123456789)', act_id } });
    continue;
  }
  out.push({ json: { act_id, date_preset, client_name, slack_channel_id, strategy, client_id } });
}
return out.length ? out : [{ json: { error: 'Sin items de entrada' } }];

const prep = $('Preparar input').first().json;
if (prep.error) return [{ json: prep }];
const allItems = $input.all();
let insightsAcc = null;
let insightsAd = [];
for (const it of allItems) {
  const j = it.json;
  if (j.error) return [{ json: { ...prep, error: j.error?.message || JSON.stringify(j.error) } }];
  const data = Array.isArray(j.data) ? j.data : [];
  if (data.length >= 1) {
    if (data[0].ad_id) insightsAd = data;
    else insightsAcc = data[0];
  }
}
const spend = parseFloat(insightsAcc?.spend || 0) || 0;
const impr = parseInt(insightsAcc?.impressions || 0, 10) || 0;
const clicks = parseInt(insightsAcc?.clicks || 0, 10) || 0;
const ctr = insightsAcc?.ctr || '0';
let leads = 0;
const actions = insightsAcc?.actions || [];
for (const a of actions) {
  if (a.action_type === 'lead') { leads = parseInt(a.value || 0, 10) || 0; break; }
}
const cpl = leads > 0 ? (spend / leads).toFixed(0) : null;
const rows = insightsAd.map(d => {
  const s = parseFloat(d.spend || 0) || 0;
  let l = 0;
  for (const a of (d.actions || [])) {
    if (a.action_type === 'lead') { l = parseInt(a.value || 0, 10) || 0; break; }
  }
  const cplAd = l > 0 ? s / l : 999999;
  return { ad_id: d.ad_id, ad_name: (d.ad_name || '').slice(0, 50), spend: s, leads: l, cpl: cplAd };
});
rows.sort((a, b) => a.cpl - b.cpl);
const ganadores = rows.filter(r => r.leads > 0).slice(0, 5);
const perdedores = rows.filter(r => r.spend > 0 && r.leads === 0).slice(0, 3);
if (rows.length && perdedores.length === 0) perdedores.push(...rows.filter(r => r.leads > 0).slice(-2));
return [{ json: {
  ...prep,
  metrics: { spend, impressions: impr, clicks, ctr, leads, cpl },
  ganadores,
  perdedores,
  period: prep.date_preset
} }];

const j = $input.first().json;
if (j.error) return [{ json: j }];
const g = (j.ganadores || []).map(x => x.ad_name + ' (CPL ' + (x.cpl?.toFixed?.(0) || x.cpl) + ')').join(', ');
const p = (j.perdedores || []).map(x => x.ad_name).join(', ');
const prompt = `Eres un analista de Meta Ads. Genera un reporte BREVE (máx 150 palabras).

Métricas (${j.period}): Gasto ${j.metrics?.spend} | Impresiones ${j.metrics?.impressions} | CTR ${j.metrics?.ctr} | Leads ${j.metrics?.leads} | CPL ${j.metrics?.cpl || 'N/A'}
Estrategia: ${j.strategy || 'No definida'}
Ganadores (mantener): ${g || 'Ninguno'}
Perdedores (revisar): ${p || 'Ninguno'}

Responde en 3 partes:
1. RESUMEN: ¿Vamos hacia el objetivo? (mejorando/estable/hay que optimizar)
2. PROBLEMA (si hay): Una línea
3. ACCIONES (1-3): Concretas y breves.

Sé directo.`;
return [{ json: { ...j, prompt } }];

const fmt = $('Ganadores y perdedores').first().json;
const req = $input.first().json;
if (fmt.error) return [{ json: fmt }];
const aiContent = req.choices?.[0]?.message?.content || req.error?.message || 'Sin resumen';
return [{ json: { ...fmt, resumen_ia: aiContent } }];
